import { useCallback, useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Link, useLocation } from "react-router-dom";
import DashboardLayout from "../layouts/DashboardLayout";
import Modal from "../components/Modal";
import { Feedback } from "../components/Feedback";
import { StatCard } from "../components/StatCard";
import { StatusBadge } from "../components/StatusBadge";
import { Toast } from "../components/Toast";
import { endpoints } from "../lib/api";
import { getAuthToken } from "../lib/auth";
import { useRequest } from "../hooks/useRequest";
import type {
  SNMPCredential, SNMPCredentialInput, SNMPDeviceProfile, SNMPDiscoveryCandidate,
  SNMPInterface, SNMPMetric, SNMPOIDDefinition, SNMPPollRun, SNMPStateChange,
  SNMPTarget, SNMPTargetInput, User,
} from "../lib/types";
import "../styles/snmp.css";

const tabs = [
  ["", "Overview"], ["targets", "Targets"], ["credentials", "Credentials"],
  ["profiles", "Profiles"], ["oids", "OIDs"], ["candidates", "Candidates"],
  ["interfaces", "Interfaces"], ["poll-runs", "Poll runs"], ["metrics", "Metrics"],
  ["state-changes", "State changes"], ["retention", "Retention"], ["reports", "Reports"],
] as const;
const fmt = (value?: string|null) => value ? new Date(value).toLocaleString() : "Never";
const duration = (value?: number|null) => value == null ? "—" : value < 1000 ? `${value} ms` : `${(value/1000).toFixed(1)} s`;
const value = (metric?: SNMPMetric|null) => metric ? `${metric.value_numeric ?? metric.value_text ?? "—"}${metric.unit ? ` ${metric.unit}` : ""}` : "No data";
const health = (target:SNMPTarget) => !target.enabled ? "disabled" : target.consecutive_failures > 0 ? "failed" : target.last_successful_poll_at ? "healthy" : "unknown";
const message = (error:unknown) => error instanceof Error ? error.message : "The operation could not be completed.";

const SNMP_EVENTS = new Set(["snmp_target_test_started","snmp_target_test_completed","snmp_poll_started","snmp_poll_progress","snmp_poll_completed","snmp_poll_failed","snmp_candidate_updated","snmp_device_onboarded","snmp_interface_state_changed","snmp_device_reboot_detected","snmp_metric_summary_updated"]);
function useSNMPLive(reload:()=>void) {
  useEffect(()=>{
    let closed=false, socket:WebSocket|undefined, retry:number|undefined;
    const connect=()=>{
      const token=getAuthToken(); if(!token)return;
      const fallback=import.meta.env.DEV?"ws://127.0.0.1:8001/ws/dashboard":`${location.protocol==="https:"?"wss:":"ws:"}//${location.host}/ws/dashboard`;
      try{socket=new WebSocket(import.meta.env.VITE_WS_URL??fallback,["hiop",token]);socket.onmessage=e=>{try{const item=JSON.parse(String(e.data)) as {type?:string;event?:string};if(SNMP_EVENTS.has(item.type??item.event??""))reload()}catch{/* ignore */}};socket.onclose=()=>{if(!closed)retry=window.setTimeout(connect,5000)}}catch{/* polling remains */}
    };connect();return()=>{closed=true;if(retry)clearTimeout(retry);socket?.close()};
  },[reload]);
}

export default function SNMPPage(){
  const location=useLocation(); const user=useRequest(endpoints.me,[]);
  const parts=location.pathname.replace(/^\/snmp\/?/,"").split("/").filter(Boolean);
  const section=parts[0]??"", id=parts[1];
  if(user.loading||user.error||!user.data)return <DashboardLayout><Feedback loading={user.loading} error={user.error} onRetry={user.reload}/></DashboardLayout>;
  return <DashboardLayout><div className="snmp-title"><div><small>Infrastructure monitoring</small><h1>SNMP Monitoring</h1><p>Secure configuration, reviewed onboarding, interfaces, health, and bounded metrics.</p></div><span className="snmp-read-mode">{user.data.role==="admin"?"Administrator controls":"Read-only monitoring"}</span></div>
    <nav className="snmp-tabs" aria-label="SNMP sections">{tabs.map(([path,label])=><Link key={path} className={section===path?"active":""} to={`/snmp${path?`/${path}`:""}`}>{label}</Link>)}</nav>
    {section===""&&<Overview user={user.data}/>}
    {section==="targets"&&(id?<TargetDetail id={id} user={user.data}/>:<Targets user={user.data}/>)}
    {section==="credentials"&&<Credentials user={user.data}/>}
    {section==="profiles"&&<Profiles user={user.data}/>}
    {section==="oids"&&<Oids user={user.data}/>}
    {section==="candidates"&&(id?<CandidateDetail id={id} user={user.data}/>:<Candidates user={user.data}/>)}
    {section==="interfaces"&&(id?<InterfaceDetail id={id}/>:<Interfaces/>)}
    {section==="poll-runs"&&(id?<PollDetail id={id} user={user.data}/>:<PollRuns user={user.data}/>)}
    {section==="metrics"&&<MetricExplorer/>}{section==="state-changes"&&<StateChanges/>}
    {section==="retention"&&<Retention user={user.data}/>}
    {section==="reports"&&<SNMPReports/>}
  </DashboardLayout>
}

function Overview({user}:{user:User}){
  const targets=useRequest(()=>endpoints.snmpTargets({page_size:100}),[]);
  const candidates=useRequest(()=>endpoints.snmpCandidates({page_size:100}),[]);
  const runs=useRequest(()=>endpoints.snmpPollRuns({page_size:10}),[]);
  const interfaces=useRequest(()=>endpoints.snmpInterfaces({page_size:100}),[]);
  const states=useRequest(()=>endpoints.snmpStateChanges({page_size:8}),[]);
  const reload=useCallback(()=>{void targets.reload();void candidates.reload();void runs.reload();void interfaces.reload();void states.reload()},[targets,candidates,runs,interfaces,states]);
  useSNMPLive(reload); useEffect(()=>{const timer=setInterval(reload,30000);return()=>clearInterval(timer)},[reload]);
  if(targets.loading||targets.error||!targets.data)return <Feedback loading={targets.loading} error={targets.error} onRetry={reload}/>;
  const list=targets.data.items, runItems=runs.data?.items??[], ints=interfaces.data?.items??[];
  const completed=runItems.filter(r=>r.status==="completed").length;
  return <><section className="snmp-kpis stats-grid" aria-label="SNMP overview">
    <StatCard label="Targets" value={targets.data.total} detail={`${list.filter(t=>health(t)==="healthy").length} healthy`} icon="network"/>
    <StatCard label="Failed targets" value={list.filter(t=>t.consecutive_failures>0).length} detail="Consecutive SNMP failures" icon="warning"/>
    <StatCard label="Pending candidates" value={(candidates.data?.items??[]).filter(c=>c.review_status==="pending"||c.review_status==="matched").length} detail="Administrator review required" icon="discovery"/>
    <StatCard label="Interfaces" value={interfaces.data?.total??0} detail={`${ints.filter(i=>i.operational_status!=="1"||i.is_missing).length} down or missing`} icon="devices"/>
    <StatCard label="Poll success" value={runItems.length?`${Math.round(completed/runItems.length*100)}%`:"—"} detail="Recent bounded runs" icon="check"/>
    <StatCard label="Recent reboots" value={(states.data?.items??[]).filter(s=>s.state_type==="device_reboot").length} detail="State history window" icon="audit"/>
  </section>
  <div className="snmp-dashboard-grid"><Panel title="Infrastructure health" copy="Current target state from real target and poll APIs."><HealthBars targets={list}/></Panel><Panel title="Quick actions" copy="All network actions remain explicit and administrator controlled."><div className="snmp-actions"><Link className="primary-action" to="/snmp/targets">Add or test target</Link><Link className="secondary-action" to="/snmp/candidates">Review candidates</Link><Link className="secondary-action" to="/snmp/poll-runs">Failed polls</Link>{user.role==="admin"&&<Link className="secondary-action" to="/snmp/credentials">Credentials</Link>}</div></Panel></div>
  <div className="snmp-dashboard-grid"><Panel title="Recent poll runs" copy="Live events trigger a controlled refetch; polling is the fallback."><RunTable rows={runItems}/></Panel><Panel title="Recent state changes" copy="Operational history only—these are not alerts."><StateList rows={states.data?.items??[]}/></Panel></div>
  <Panel title="Pending onboarding candidates" copy="Nothing is promoted automatically."><CandidateTable rows={(candidates.data?.items??[]).slice(0,6)} admin={user.role==="admin"}/></Panel></>;
}

function Credentials({user}:{user:User}){
  const data=useRequest(()=>endpoints.snmpCredentials({page_size:100}),[]); const [edit,setEdit]=useState<SNMPCredential|null|undefined>(); const [rotate,setRotate]=useState<SNMPCredential|null>(); const [notice,setNotice]=useState("");
  if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;
  return <><SectionTitle title="Credential profiles" copy="Secrets are write-only. Only configured-state indicators are returned." action={user.role==="admin"?<button className="primary-action" onClick={()=>setEdit(null)}>New credential</button>:undefined}/>
    {!data.data.items.length?<Feedback empty="Create an encrypted credential profile before adding targets."/>:<Table heads={["Name","Version","Security","Username","Secrets","Status","Updated","Actions"]}>{data.data.items.map(c=><tr key={c.id}><td><strong>{c.name}</strong><small>{c.description||"No description"}</small></td><td>{c.version}</td><td>{c.security_level}</td><td>{c.username||"—"}</td><td>{[c.has_community&&"Community",c.has_authentication_secret&&"Auth",c.has_privacy_secret&&"Privacy"].filter(Boolean).join(", ")||"Not configured"}</td><td><StatusBadge status={c.enabled?"enabled":"disabled"}/></td><td>{fmt(c.updated_at)}</td><td><div className="snmp-row-actions">{user.role==="admin"&&<><button onClick={()=>setEdit(c)}>Edit</button><button onClick={()=>setRotate(c)}>Rotate secret</button><button disabled={!c.enabled} onClick={()=>void endpoints.disableSNMPCredential(c.id).then(data.reload).catch(e=>setNotice(message(e)))}>Disable</button></>}</div></td></tr>)}</Table>}
    {edit!==undefined&&<CredentialForm current={edit} onClose={()=>setEdit(undefined)} onSaved={()=>{setEdit(undefined);setNotice("Credential saved without exposing secret material.");void data.reload()}}/>}
    {rotate&&<SecretRotation credential={rotate} onClose={()=>setRotate(null)} onSaved={()=>{setRotate(null);setNotice("Secret rotated. Linked targets may require device-side updates.");void data.reload()}}/>}
    {notice&&<Toast message={notice}/>}</>;
}

function CredentialForm({current,onClose,onSaved}:{current:SNMPCredential|null;onClose:()=>void;onSaved:()=>void}){
  const [form,setForm]=useState<SNMPCredentialInput>({name:current?.name??"",version:(current?.version??"v3") as "v1"|"v2c"|"v3",username:current?.username??"",security_level:current?.security_level??"authPriv",authentication_protocol:current?.authentication_protocol??"SHA256",privacy_protocol:current?.privacy_protocol??"AES128",context_name:current?.context_name??"",description:current?.description??"",enabled:current?.enabled??true});
  const [confirm,setConfirm]=useState("");const [privacyConfirm,setPrivacyConfirm]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError("");try{if(current)await endpoints.updateSNMPCredential(current.id,{name:form.name,description:form.description,enabled:form.enabled,context_name:form.context_name});else{const secret=form.version==="v3"?form.security_level==="noAuthNoPriv"?true:form.authentication_secret&&form.authentication_secret===confirm&&(form.security_level!=="authPriv"||Boolean(form.privacy_secret&&form.privacy_secret===privacyConfirm)):form.community&&form.community===confirm;if(!secret)throw new Error("Secret confirmation does not match.");await endpoints.createSNMPCredential(form)}onSaved()}catch(e){setError(message(e))}finally{setBusy(false)}};
  return <Modal title={current?"Edit credential metadata":"Create encrypted credential"} onClose={onClose}><form className="snmp-form" onSubmit={submit} autoComplete="off"><label>Name<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label>{!current&&<><label>SNMP version<select value={form.version} onChange={e=>setForm({...form,version:e.target.value as SNMPCredentialInput["version"]})}><option value="v3">v3 (preferred)</option><option value="v2c">v2c</option><option value="v1">v1 legacy</option></select></label>{form.version!=="v3"?<><label>Community<input required type="password" autoComplete="new-password" value={form.community??""} onChange={e=>setForm({...form,community:e.target.value})}/></label><SecretConfirm value={confirm} set={setConfirm}/><p className="snmp-warning">Community-based SNMP does not provide modern privacy. Production policy may reject it.</p></>:<V3Fields form={form} setForm={setForm} confirm={confirm} setConfirm={setConfirm} privacyConfirm={privacyConfirm} setPrivacyConfirm={setPrivacyConfirm}/>}</>}
  <label>Description<textarea value={form.description??""} onChange={e=>setForm({...form,description:e.target.value})}/></label><label className="snmp-check"><input type="checkbox" checked={form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/>Enabled</label>{error&&<p className="form-error" role="alert">{error}</p>}<footer><button type="button" className="secondary-action" onClick={onClose}>Cancel</button><button className="primary-action" disabled={busy}>{busy?"Saving…":"Save credential"}</button></footer></form></Modal>;
}
function V3Fields({form,setForm,confirm,setConfirm,privacyConfirm,setPrivacyConfirm}:{form:SNMPCredentialInput;setForm:(f:SNMPCredentialInput)=>void;confirm:string;setConfirm:(v:string)=>void;privacyConfirm:string;setPrivacyConfirm:(v:string)=>void}){
  return <><label>Username<input required value={form.username??""} onChange={e=>setForm({...form,username:e.target.value})}/></label><label>Security level<select value={form.security_level} onChange={e=>setForm({...form,security_level:e.target.value})}><option>noAuthNoPriv</option><option>authNoPriv</option><option>authPriv</option></select></label>{form.security_level!=="noAuthNoPriv"&&<><label>Authentication protocol<select value={form.authentication_protocol} onChange={e=>setForm({...form,authentication_protocol:e.target.value})}><option>SHA256</option><option>SHA</option><option>SHA224</option><option>SHA384</option><option>SHA512</option></select></label><label>Authentication secret<input required type="password" autoComplete="new-password" value={form.authentication_secret??""} onChange={e=>setForm({...form,authentication_secret:e.target.value})}/></label><SecretConfirm value={confirm} set={setConfirm}/></>}{form.security_level==="authPriv"&&<><label>Privacy protocol<select value={form.privacy_protocol} onChange={e=>setForm({...form,privacy_protocol:e.target.value})}><option>AES128</option><option>AES192</option><option>AES256</option></select></label><label>Privacy secret<input required type="password" autoComplete="new-password" value={form.privacy_secret??""} onChange={e=>setForm({...form,privacy_secret:e.target.value})}/></label><label>Confirm privacy secret<input required type="password" autoComplete="new-password" value={privacyConfirm} onChange={e=>setPrivacyConfirm(e.target.value)}/></label></>}<p className="snmp-safe">SNMPv3 with authentication and privacy is preferred. Secrets exist only in this form until submission.</p></>;
}
function SecretConfirm({value,set}:{value:string;set:(v:string)=>void}){return <label>Confirm secret<input required type="password" autoComplete="new-password" value={value} onChange={e=>set(e.target.value)}/></label>}
function SecretRotation({credential,onClose,onSaved}:{credential:SNMPCredential;onClose:()=>void;onSaved:()=>void}){const [secret,setSecret]=useState(""),[confirm,setConfirm]=useState(""),[kind,setKind]=useState(credential.version==="v3"?"authentication_secret":"community"),[error,setError]=useState("");const submit=async(e:FormEvent)=>{e.preventDefault();if(secret!==confirm){setError("Secret confirmation does not match.");return}try{await endpoints.rotateSNMPSecret(credential.id,{[kind]:secret});setSecret("");setConfirm("");onSaved()}catch(e){setError(message(e))}};return <Modal title={`Rotate ${credential.name} secret`} onClose={onClose}><form className="snmp-form" onSubmit={submit} autoComplete="off">{credential.version==="v3"&&<label>Secret type<select value={kind} onChange={e=>setKind(e.target.value)}><option value="authentication_secret">Authentication</option><option value="privacy_secret">Privacy</option></select></label>}<label>New secret<input type="password" required autoComplete="new-password" value={secret} onChange={e=>setSecret(e.target.value)}/></label><SecretConfirm value={confirm} set={setConfirm}/><p className="snmp-warning">Update the device-side credential consistently. Existing values cannot be viewed or recovered.</p>{error&&<p className="form-error">{error}</p>}<footer><button type="button" className="secondary-action" onClick={onClose}>Cancel</button><button className="primary-action">Rotate securely</button></footer></form></Modal>}

function Targets({user}:{user:User}){
  const data=useRequest(()=>endpoints.snmpTargets({page_size:100}),[]), credentials=useRequest(()=>endpoints.snmpCredentials({page_size:100}),[]);
  const [form,setForm]=useState(false),[test,setTest]=useState<SNMPTarget|null>(null),[collect,setCollect]=useState<SNMPTarget|null>(null),[search,setSearch]=useState("");
  const rows=(data.data?.items??[]).filter(t=>`${t.name} ${t.hostname} ${t.ip_address}`.toLowerCase().includes(search.toLowerCase()));
  if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;
  return <><SectionTitle title="SNMP targets" copy="Authorized endpoints and their current safe health state." action={user.role==="admin"?<button className="primary-action" onClick={()=>setForm(true)}>Add target</button>:undefined}/><div className="snmp-toolbar"><label>Search targets<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Name, host, or IP"/></label></div>
  {!rows.length?<Feedback empty="No SNMP targets match the current filters."/>:<Table heads={["Target","Endpoint","Version","Credential","Status","Last test","Last poll","Failures","Actions"]}>{rows.map(t=><tr key={t.id}><td><Link to={`/snmp/targets/${t.id}`}><strong>{t.name}</strong></Link><small>{t.hostname||"No hostname"}</small></td><td className="snmp-mono">{t.ip_address}:{t.port}</td><td>{t.version}</td><td>{credentials.data?.items.find(c=>c.id===t.credential_id)?.name??"Loading…"}</td><td><StatusBadge status={health(t)}/></td><td>{fmt(t.last_tested_at)}<small>{t.last_test_status||"Never tested"}</small></td><td>{fmt(t.last_successful_poll_at)}</td><td>{t.consecutive_failures}</td><td><div className="snmp-row-actions"><Link to={`/snmp/targets/${t.id}`}>View</Link>{user.role==="admin"&&<><button onClick={()=>setTest(t)}>Test</button><button onClick={()=>setCollect(t)}>Collect</button></>}</div></td></tr>)}</Table>}
  {form&&credentials.data&&<TargetForm credentials={credentials.data.items} onClose={()=>setForm(false)} onSaved={()=>{setForm(false);void data.reload()}}/>}{test&&<TargetTest target={test} onClose={()=>setTest(null)} onDone={data.reload}/>} {collect&&<CollectionDialog target={collect} onClose={()=>setCollect(null)}/>}</>;
}
function TargetForm({credentials,current,onClose,onSaved}:{credentials:SNMPCredential[];current?:SNMPTarget;onClose:()=>void;onSaved:()=>void}){const [form,setForm]=useState<SNMPTargetInput>(current?{name:current.name,credential_id:current.credential_id,hostname:current.hostname,ip_address:current.ip_address,port:current.port,version:current.version as SNMPTargetInput["version"],enabled:current.enabled,polling_enabled:current.polling_enabled,timeout_seconds:current.timeout_seconds,retries:current.retries,transport:"udp",context_name:current.context_name,network_zone_id:current.network_zone_id,location_id:current.location_id}:{name:"",credential_id:credentials[0]?.id??"",ip_address:"",port:161,version:(credentials[0]?.version??"v3"),enabled:true,polling_enabled:false,timeout_seconds:5,retries:1,transport:"udp",context_name:""}),[error,setError]=useState("");const compatible=credentials.filter(c=>(c.enabled||c.id===current?.credential_id)&&c.version===form.version);const submit=async(e:FormEvent)=>{e.preventDefault();try{if(current)await endpoints.updateSNMPTarget(current.id,form);else await endpoints.createSNMPTarget(form);onSaved()}catch(e){setError(message(e))}};return <Modal title={current?"Edit SNMP target":"Add authorized SNMP target"} onClose={onClose}><form className="snmp-form snmp-form-grid" onSubmit={submit}><label>Name<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Version<select disabled={Boolean(current)} value={form.version} onChange={e=>setForm({...form,version:e.target.value as SNMPTargetInput["version"],credential_id:""})}><option>v3</option><option>v2c</option><option>v1</option></select></label><label>Credential<select required value={form.credential_id} onChange={e=>setForm({...form,credential_id:e.target.value})}><option value="">Select compatible profile</option>{compatible.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>IP address<input required inputMode="decimal" value={form.ip_address} onChange={e=>setForm({...form,ip_address:e.target.value})}/></label><label>Hostname<input value={form.hostname??""} onChange={e=>setForm({...form,hostname:e.target.value||null})}/></label><label>Port<input type="number" min="1" max="65535" value={form.port} onChange={e=>setForm({...form,port:Number(e.target.value)})}/></label><label>Timeout seconds<input type="number" min="1" max="60" value={form.timeout_seconds} onChange={e=>setForm({...form,timeout_seconds:Number(e.target.value)})}/></label><label>Retries<input type="number" min="0" max="10" value={form.retries} onChange={e=>setForm({...form,retries:Number(e.target.value)})}/></label><label>Context<input value={form.context_name} onChange={e=>setForm({...form,context_name:e.target.value})}/></label><label className="snmp-check"><input type="checkbox" checked={form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/>Enabled</label><p className="snmp-safe">Saving validates authorization and configuration but does not poll the target.</p>{error&&<p className="form-error">{error}</p>}<footer><button type="button" className="secondary-action" onClick={onClose}>Cancel</button><button className="primary-action">Save target</button></footer></form></Modal>}
function TargetTest({target,onClose,onDone}:{target:SNMPTarget;onClose:()=>void;onDone:()=>void}){const result=useRequest(()=>endpoints.testSNMPTarget(target.id),[target.id]);useEffect(()=>{if(result.data)onDone()},[result.data,onDone]);const stages=["Configuration validation","Authorized-range validation","Credential decryption","Network transport","SNMP authentication","System identity","Profile detection"];return <Modal title={`Test ${target.name}`} onClose={onClose}>{result.loading?<Feedback loading/>:result.error?<Feedback error={result.error} onRetry={result.reload}/>:result.data&&<div className="snmp-test"><div className="snmp-stage-list">{stages.map((stage,index)=><div key={stage}><span aria-hidden="true">✓</span><strong>{stage}</strong><small>{index<5?"Validated":result.data?.overall_status}</small></div>)}</div><dl><Detail label="Overall status" value={result.data.overall_status}/><Detail label="Detected version" value={result.data.detected_version}/><Detail label="Duration" value={duration(result.data.duration_ms)}/><Detail label="Tested" value={fmt(result.data.tested_at)}/>{Object.entries(result.data.identity??{}).map(([key,item])=><Detail key={key} label={key.replaceAll("."," ")} value={item.value_text??item.value_numeric}/>)}</dl>{result.data.warnings.map(w=><p className="snmp-warning" key={w}>{w}</p>)}</div>}</Modal>}
function CollectionDialog({target,onClose}:{target:SNMPTarget;onClose:()=>void}){const groups=["availability","system","interface_inventory","interface_performance","device_performance","all_profile_metrics"],[selected,setSelected]=useState(["availability"]),[busy,setBusy]=useState(false),[notice,setNotice]=useState("");const run=async()=>{setBusy(true);try{const result=await endpoints.collectSNMPTarget(target.id,selected);setNotice(`Run ${result.poll_run_id} finished with status ${result.status}.`)}catch(e){setNotice(message(e))}finally{setBusy(false)}};return <Modal title={`Collect from ${target.name}`} onClose={onClose}><div className="snmp-form"><p className="snmp-warning">This explicitly contacts the saved authorized target. No arbitrary OIDs are accepted.</p><fieldset><legend>Approved groups</legend>{groups.map(g=><label className="snmp-check" key={g}><input type="checkbox" checked={selected.includes(g)} onChange={e=>setSelected(e.target.checked?[...selected,g]:selected.filter(x=>x!==g))}/>{g.replaceAll("_"," ")}</label>)}</fieldset>{notice&&<p role="status">{notice}</p>}<footer><button className="secondary-action" onClick={onClose}>Close</button><button className="primary-action" disabled={busy||!selected.length} onClick={()=>void run()}>{busy?"Collecting…":"Confirm collection"}</button></footer></div></Modal>}

function TargetDetail({id,user}:{id:string;user:User}){const target=useRequest(()=>endpoints.snmpTarget(id),[id]), credentials=useRequest(()=>endpoints.snmpCredentials({page_size:100}),[]), metrics=useRequest(()=>endpoints.snmpTargetMetrics(id,{page_size:100}),[id]), interfaces=useRequest(()=>endpoints.snmpTargetInterfaces(id,{page_size:100}),[id]), runs=useRequest(()=>endpoints.snmpPollRuns({target_id:id,page_size:20}),[id]), states=useRequest(()=>endpoints.snmpStateChanges({target_id:id,page_size:20}),[id]);const [test,setTest]=useState(false),[collect,setCollect]=useState(false),[edit,setEdit]=useState(false);const reload=useCallback(()=>{void target.reload();void metrics.reload();void interfaces.reload();void runs.reload();void states.reload()},[target,metrics,interfaces,runs,states]);useSNMPLive(reload);if(target.loading||target.error||!target.data)return <Feedback loading={target.loading} error={target.error} onRetry={reload}/>;const t=target.data, latest=latestMetrics(metrics.data?.items??[]);return <><SectionTitle title={t.name} copy={`${t.ip_address}:${t.port} · ${t.version}`} action={<div className="snmp-actions"><Link className="secondary-action" to="/snmp/targets">Back</Link>{user.role==="admin"&&<><button className="secondary-action" onClick={()=>setEdit(true)}>Edit</button><button className="secondary-action" onClick={()=>setTest(true)}>Test target</button><button className="primary-action" onClick={()=>setCollect(true)}>Collect now</button></>}</div>}/><section className="snmp-health-cards"><MetricCard label="Health" value={health(t)} quality={health(t)}/><MetricCard label="Response time" value={t.last_response_time_ms==null?"No data":`${t.last_response_time_ms} ms`}/><MetricCard label="Uptime" value={value(latest["system.uptime"])}/><MetricCard label="Interfaces down" value={(interfaces.data?.items??[]).filter(i=>i.operational_status!=="1"||i.is_missing).length}/><MetricCard label="Last successful poll" value={fmt(t.last_successful_poll_at)}/></section><div className="snmp-dashboard-grid"><Panel title="Identity and configuration" copy="Secrets are never returned."><dl className="snmp-detail-grid"><Detail label="Target ID" value={t.id}/><Detail label="Hostname" value={t.hostname}/><Detail label="sysObjectID" value={t.detected_sys_object_id}/><Detail label="Credential ID" value={t.credential_id}/><Detail label="Profile ID" value={t.detected_profile_id}/><Detail label="Consecutive failures" value={t.consecutive_failures}/><Detail label="Last test" value={fmt(t.last_tested_at)}/><Detail label="Last test message" value={t.last_test_message}/></dl></Panel><Panel title="Supported performance" copy="Sections appear only when matching metrics exist."><MetricSummary metrics={latest}/></Panel></div><Panel title="Metric history" copy="Bounded recent samples with quality-aware accessible chart summaries."><MetricChart metrics={metrics.data?.items??[]} metricKey={(metrics.data?.items??[])[0]?.metric_key}/></Panel><Panel title="Interfaces" copy="Stable target plus ifIndex identity."><InterfaceTable rows={(interfaces.data?.items??[]).slice(0,10)}/></Panel><div className="snmp-dashboard-grid"><Panel title="Poll runs" copy="Recent target collection history."><RunTable rows={runs.data?.items??[]}/></Panel><Panel title="State changes" copy="Reboots explain temporary counter-rate gaps."><StateList rows={states.data?.items??[]}/></Panel></div>{edit&&credentials.data&&<TargetForm current={t} credentials={credentials.data.items} onClose={()=>setEdit(false)} onSaved={()=>{setEdit(false);reload()}}/>}{test&&<TargetTest target={t} onClose={()=>setTest(false)} onDone={reload}/>} {collect&&<CollectionDialog target={t} onClose={()=>setCollect(false)}/>}</>}

function Profiles({user}:{user:User}){const data=useRequest(()=>endpoints.snmpProfiles({page_size:100}),[]);const [edit,setEdit]=useState<SNMPDeviceProfile|null|undefined>();if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;return <><SectionTitle title="Device profiles" copy="Priority-ordered, non-executable vendor and device classification." action={user.role==="admin"?<button className="primary-action" onClick={()=>setEdit(null)}>New profile</button>:undefined}/><Table heads={["Name","Vendor","Device type","Patterns","Priority","Status","Actions"]}>{data.data.items.map(p=><tr key={p.id}><td><strong>{p.name}</strong></td><td>{p.vendor||"Generic"}</td><td>{p.device_type}</td><td><small>{p.sys_object_id_pattern||"Any sysObjectID"}</small><small>{p.sys_descr_pattern||"Any description"}</small></td><td>{p.priority}</td><td><StatusBadge status={p.enabled?"enabled":"disabled"}/></td><td>{user.role==="admin"&&<button onClick={()=>setEdit(p)}>Edit</button>}</td></tr>)}</Table>{edit!==undefined&&<ProfileForm current={edit} onClose={()=>setEdit(undefined)} onSaved={()=>{setEdit(undefined);void data.reload()}}/>}</>}
function ProfileForm({current,onClose,onSaved}:{current:SNMPDeviceProfile|null;onClose:()=>void;onSaved:()=>void}){const [form,setForm]=useState({name:current?.name??"",vendor:current?.vendor??"",device_type:current?.device_type??"generic_snmp_device",sys_object_id_pattern:current?.sys_object_id_pattern??"",sys_descr_pattern:current?.sys_descr_pattern??"",priority:current?.priority??100,enabled:current?.enabled??true,profile_data:current?.profile_data??{}}),[error,setError]=useState("");const submit=async(e:FormEvent)=>{e.preventDefault();try{if(current)await endpoints.updateSNMPProfile(current.id,form);else await endpoints.createSNMPProfile(form);onSaved()}catch(e){setError(message(e))}};return <Modal title={current?"Edit profile":"Create profile"} onClose={onClose}><form className="snmp-form" onSubmit={submit}><label>Name<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Vendor<input value={form.vendor} onChange={e=>setForm({...form,vendor:e.target.value})}/></label><label>Device type<input required value={form.device_type} onChange={e=>setForm({...form,device_type:e.target.value})}/></label><label>sysObjectID pattern<input value={form.sys_object_id_pattern} onChange={e=>setForm({...form,sys_object_id_pattern:e.target.value})}/></label><label>sysDescr pattern<input value={form.sys_descr_pattern} onChange={e=>setForm({...form,sys_descr_pattern:e.target.value})}/></label><label>Priority<input type="number" min="0" value={form.priority} onChange={e=>setForm({...form,priority:Number(e.target.value)})}/></label><p className="snmp-safe">Lower numbers match first. Patterns classify text only and cannot execute code.</p>{error&&<p className="form-error">{error}</p>}<footer><button type="button" className="secondary-action" onClick={onClose}>Cancel</button><button className="primary-action">Save</button></footer></form></Modal>}

function Oids({user}:{user:User}){const data=useRequest(()=>endpoints.snmpOids({page_size:100}),[]),profiles=useRequest(()=>endpoints.snmpProfiles({page_size:100}),[]);const [search,setSearch]=useState(""),[edit,setEdit]=useState<SNMPOIDDefinition|null|undefined>();const rows=(data.data?.items??[]).filter(o=>`${o.name} ${o.oid} ${o.metric_key}`.toLowerCase().includes(search.toLowerCase()));if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;return <><SectionTitle title="Approved OID definitions" copy="Validated metric definitions only; this page never executes a network request." action={user.role==="admin"?<button className="primary-action" onClick={()=>setEdit(null)}>New OID</button>:undefined}/><div className="snmp-toolbar"><label>Search OIDs<input value={search} onChange={e=>setSearch(e.target.value)}/></label></div><Table heads={["Name","OID","Metric key","Type","Unit","Collection","Criticality","Status","Actions"]}>{rows.map(o=><tr key={o.id}><td><strong>{o.name}</strong></td><td className="snmp-mono">{o.oid}</td><td>{o.metric_key}</td><td>{o.data_type}</td><td>{o.unit||"—"}</td><td>{o.collection_type}</td><td>{o.criticality}</td><td><StatusBadge status={o.enabled?"enabled":"disabled"}/></td><td>{user.role==="admin"&&<button onClick={()=>setEdit(o)}>Edit</button>}</td></tr>)}</Table>{edit!==undefined&&profiles.data&&<OIDForm current={edit} profiles={profiles.data.items} onClose={()=>setEdit(undefined)} onSaved={()=>{setEdit(undefined);void data.reload()}}/>}</>}
function OIDForm({current,profiles,onClose,onSaved}:{current:SNMPOIDDefinition|null;profiles:SNMPDeviceProfile[];onClose:()=>void;onSaved:()=>void}){const [form,setForm]=useState({name:current?.name??"",oid:current?.oid??"",metric_key:current?.metric_key??"",description:current?.description??"",data_type:current?.data_type??"gauge",unit:current?.unit??"",scale_factor:current?.scale_factor??1,collection_type:current?.collection_type??"scalar",profile_id:current?.profile_id??null,enabled:current?.enabled??true,criticality:current?.criticality??"normal",transform_type:current?.transform_type??"identity"}),[error,setError]=useState("");const submit=async(e:FormEvent)=>{e.preventDefault();try{if(current)await endpoints.updateSNMPOid(current.id,{name:form.name,description:form.description,enabled:form.enabled,scale_factor:form.scale_factor,transform_type:form.transform_type});else await endpoints.createSNMPOid(form);onSaved()}catch(e){setError(message(e))}};return <Modal title={current?"Edit OID definition":"Create approved OID definition"} onClose={onClose}><form className="snmp-form snmp-form-grid" onSubmit={submit}><label>Name<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>OID<input required disabled={Boolean(current)} pattern="[0-2](\\.[0-9]+)+" value={form.oid} onChange={e=>setForm({...form,oid:e.target.value})}/></label><label>Metric key<input required disabled={Boolean(current)} pattern="[a-z][a-z0-9_.-]+" value={form.metric_key} onChange={e=>setForm({...form,metric_key:e.target.value})}/></label><label>Profile<select disabled={Boolean(current)} value={form.profile_id??""} onChange={e=>setForm({...form,profile_id:e.target.value||null})}><option value="">Standard/global</option>{profiles.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>Data type<select disabled={Boolean(current)} value={form.data_type} onChange={e=>setForm({...form,data_type:e.target.value})}>{["string","integer","float","counter","gauge","timeticks","enum"].map(x=><option key={x}>{x}</option>)}</select></label><label>Collection type<select disabled={Boolean(current)} value={form.collection_type} onChange={e=>setForm({...form,collection_type:e.target.value})}>{["scalar","table","counter","gauge","timeticks","string","integer","enum"].map(x=><option key={x}>{x}</option>)}</select></label><label>Unit<input value={form.unit} onChange={e=>setForm({...form,unit:e.target.value})}/></label><label>Scale factor<input type="number" min=".000001" step="any" value={form.scale_factor} onChange={e=>setForm({...form,scale_factor:Number(e.target.value)})}/></label><label>Transform<select value={form.transform_type} onChange={e=>setForm({...form,transform_type:e.target.value})}>{["identity","scale","timeticks_to_seconds","enum_map","bytes_to_bits"].map(x=><option key={x}>{x}</option>)}</select></label><label>Criticality<select disabled={Boolean(current)} value={form.criticality} onChange={e=>setForm({...form,criticality:e.target.value})}>{["low","normal","high","critical"].map(x=><option key={x}>{x}</option>)}</select></label><p className="snmp-safe">Validation only. Saving never executes this OID against a target.</p>{error&&<p className="form-error">{error}</p>}<footer><button type="button" className="secondary-action" onClick={onClose}>Cancel</button><button className="primary-action">Save definition</button></footer></form></Modal>}

function Candidates({user}:{user:User}){const data=useRequest(()=>endpoints.snmpCandidates({page_size:100}),[]);if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;const rows=data.data.items;return <><SectionTitle title="Candidate review queue" copy="System identity and explainable matches remain staged until administrator approval."/><section className="snmp-health-cards"><MetricCard label="Pending" value={rows.filter(c=>c.review_status==="pending").length}/><MetricCard label="Matched" value={rows.filter(c=>c.review_status==="matched").length}/><MetricCard label="Conflicts" value={rows.filter(c=>c.review_status==="conflict").length} quality="warning"/><MetricCard label="Approved" value={rows.filter(c=>c.review_status==="approved").length}/><MetricCard label="Ignored / rejected" value={rows.filter(c=>["ignored","rejected"].includes(c.review_status)).length}/></section>{!rows.length?<Feedback empty="No SNMP discovery candidates are waiting for review."/>:<CandidateTable rows={rows} admin={user.role==="admin"}/>}</>}
function CandidateTable({rows,admin}:{rows:SNMPDiscoveryCandidate[];admin:boolean}){return <Table heads={["Identity","Target","sysObjectID","Vendor/type","Confidence","Review","Actions"]}>{rows.map(c=><tr key={c.id}><td><strong>{c.sys_name||"Unnamed candidate"}</strong><small>{c.sys_location||"No location"}</small></td><td className="snmp-mono">{c.target_id}</td><td className="snmp-mono">{c.sys_object_id||"—"}</td><td>{c.vendor_guess||"Unknown"}<small>{c.device_type_guess||"Generic"}</small></td><td>{Math.round(c.confidence_score)}%</td><td><StatusBadge status={c.review_status}/></td><td><Link to={`/snmp/candidates/${c.id}`}>{admin?"Review":"View"}</Link></td></tr>)}</Table>}
function CandidateDetail({id,user}:{id:string;user:User}){
  const candidate=useRequest(()=>endpoints.snmpCandidate(id),[id]), matches=useRequest(()=>endpoints.snmpCandidateMatches(id),[id]), plan=useRequest(()=>endpoints.snmpOnboardingPlan(id),[id]);
  const [notice,setNotice]=useState(""),[action,setAction]=useState<"create"|"link"|"enrich"|null>(null);
  if(candidate.loading||candidate.error||!candidate.data)return <Feedback loading={candidate.loading} error={candidate.error} onRetry={candidate.reload}/>;
  const c=candidate.data;
  const act=async(review:"ignore"|"reject"|"restore")=>{try{await endpoints.reviewSNMPCandidate(id,review,c.updated_at);setNotice(`Candidate ${review} completed.`);void candidate.reload()}catch(e){setNotice(message(e))}};
  return <><SectionTitle title={c.sys_name||"SNMP candidate"} copy="Compare evidence and review safely before inventory mutation." action={<Link className="secondary-action" to="/snmp/candidates">Back to queue</Link>}/>
    <div className="snmp-comparison"><Panel title="SNMP identity" copy="Observed system values."><dl><Detail label="sysName" value={c.sys_name}/><Detail label="sysDescr" value={c.sys_descr}/><Detail label="sysObjectID" value={c.sys_object_id}/><Detail label="sysLocation" value={c.sys_location}/><Detail label="Vendor guess" value={c.vendor_guess}/><Detail label="Device type" value={c.device_type_guess}/></dl></Panel>
    <Panel title="Inventory and Discovery matches" copy="IP-only evidence is never exact.">{matches.loading?<Feedback loading/>:matches.data?.items.length?matches.data.items.map(m=><article className="snmp-match" key={m.id}><header><strong>{m.candidate_type.replaceAll("_"," ")}</strong><StatusBadge status={m.match_level}/></header><p>Score {m.match_score}% · {m.recommended_action}</p><small>Matches: {m.matching_fields.join(", ")||"none"}</small><small>Conflicts: {m.conflicting_fields.join(", ")||"none"}</small></article>):<Feedback empty="Run matching to produce explainable candidates."/>}</Panel>
    <Panel title="Onboarding plan" copy="Missing mandatory fields block device creation.">{plan.loading?<Feedback loading/>:plan.data&&<><dl>{Object.entries(plan.data.suggestions).map(([k,v])=><Detail key={k} label={k.replaceAll("_"," ")} value={v}/>)}</dl>{plan.data.missing_required_fields.length?<p className="snmp-warning">Required administrator input: {plan.data.missing_required_fields.join(", ")}</p>:<p className="snmp-safe">All mandatory fields are present.</p>}</>}</Panel></div>
    {user.role==="admin"&&<div className="snmp-review-bar"><button onClick={()=>void endpoints.matchSNMPCandidate(id).then(matches.reload).catch(e=>setNotice(message(e)))}>Recompute matches</button><button onClick={()=>setAction("create")}>Approve as new</button><button onClick={()=>setAction("link")}>Link existing</button><button onClick={()=>setAction("enrich")}>Enrich existing</button><button onClick={()=>void act(c.review_status==="ignored"||c.review_status==="rejected"?"restore":"ignore")}>{c.review_status==="ignored"||c.review_status==="rejected"?"Restore":"Ignore"}</button><button className="danger-action" onClick={()=>void act("reject")}>Reject</button></div>}
    {action&&plan.data&&<CandidateActionDialog action={action} candidate={c} plan={plan.data} onClose={()=>setAction(null)} onSaved={()=>{setAction(null);setNotice("Reviewed candidate action completed.");void candidate.reload();void plan.reload()}}/>}{notice&&<Toast message={notice}/>}</>;
}

function CandidateActionDialog({action,candidate,plan,onClose,onSaved}:{action:"create"|"link"|"enrich";candidate:SNMPDiscoveryCandidate;plan:import("../lib/types").SNMPOnboardingPlan;onClose:()=>void;onSaved:()=>void}){
  const devices=useRequest(endpoints.devices,[]),[deviceId,setDeviceId]=useState(""),[overwrite,setOverwrite]=useState(false),[fields,setFields]=useState(["hostname","brand","device_type","ip_address","location"]),[error,setError]=useState(""),[busy,setBusy]=useState(false);
  const suggestions=plan.suggestions;
  const [device,setDevice]=useState<Record<string,string>>({asset_tag:"",hostname:suggestions.hostname??"",device_type:suggestions.device_type??"",brand:suggestions.brand??"",model:"",serial_number:"",department:"",location:suggestions.location??"",ip_address:suggestions.ip_address??"",mac_address:"",inventory_status:"Active"});
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError("");try{if(action==="create")await endpoints.approveSNMPCandidate(candidate.id,device,plan.candidate_updated_at);else if(action==="link")await endpoints.linkSNMPCandidate(candidate.id,deviceId,plan.candidate_updated_at);else await endpoints.enrichSNMPCandidate(candidate.id,deviceId,fields,overwrite,plan.candidate_updated_at);onSaved()}catch(e){setError(message(e))}finally{setBusy(false)}};
  return <Modal title={action==="create"?"Approve as new inventory device":action==="link"?"Link existing device":"Enrich existing device"} onClose={onClose}><form className="snmp-form snmp-form-grid" onSubmit={submit}>
    {action==="create"?Object.entries(device).map(([key,current])=><label key={key}>{key.replaceAll("_"," ")}<input required={key!=="inventory_status"} value={current} onChange={e=>setDevice({...device,[key]:e.target.value})}/><small>{suggestions[key]?"Suggested from SNMP; review before saving.":"Administrator input required."}</small></label>):<label>Inventory device<select required value={deviceId} onChange={e=>setDeviceId(e.target.value)}><option value="">Select device</option>{devices.data?.map(d=><option key={d.id} value={d.id}>{d.hostname} · {d.asset_tag}</option>)}</select></label>}
    {action==="enrich"&&<><fieldset><legend>Explicit fields</legend>{["hostname","brand","device_type","ip_address","location"].map(field=><label className="snmp-check" key={field}><input type="checkbox" checked={fields.includes(field)} onChange={e=>setFields(e.target.checked?[...fields,field]:fields.filter(x=>x!==field))}/>{field.replaceAll("_"," ")}</label>)}</fieldset><label className="snmp-check"><input type="checkbox" checked={overwrite} onChange={e=>setOverwrite(e.target.checked)}/>Explicitly permit overwrites</label></>}
    <p className="snmp-warning">The plan is freshness checked. Contradictory links, duplicate identifiers, missing required fields, and stale candidates are rejected by the backend.</p>{error&&<p className="form-error" role="alert">{error}</p>}<footer><button type="button" className="secondary-action" onClick={onClose}>Cancel</button><button className="primary-action" disabled={busy||(action!=="create"&&!deviceId)}>{busy?"Applying…":"Confirm reviewed action"}</button></footer>
  </form></Modal>;
}

function Interfaces(){const data=useRequest(()=>endpoints.snmpInterfaces({page_size:100}),[]),[search,setSearch]=useState(""),[down,setDown]=useState(false);const rows=(data.data?.items??[]).filter(i=>(!down||i.operational_status!=="1"||i.is_missing)&&`${i.name} ${i.description} ${i.alias}`.toLowerCase().includes(search.toLowerCase()));if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;return <><SectionTitle title="Interface inventory" copy="Global, bounded interface identity and operational state."/><div className="snmp-toolbar"><label>Search interfaces<input value={search} onChange={e=>setSearch(e.target.value)}/></label><label className="snmp-check"><input type="checkbox" checked={down} onChange={e=>setDown(e.target.checked)}/>Down or missing only</label></div>{!rows.length?<Feedback empty="No interfaces match the selected filters."/>:<InterfaceTable rows={rows}/>}</>}
function InterfaceTable({rows}:{rows:SNMPInterface[]}){return <Table heads={["Interface","Target","Index","Type","MAC","Admin","Operational","Speed","Last seen","State","Actions"]}>{rows.map(i=><tr key={i.id}><td><strong>{i.name||i.description||`Interface ${i.interface_index}`}</strong><small>{i.alias||"No alias"}</small></td><td className="snmp-mono">{i.target_id}</td><td>{i.interface_index}</td><td>{i.interface_type||"—"}</td><td className="snmp-mono">{i.mac_address||"—"}</td><td><StatusBadge status={i.admin_status==="1"?"up":"down"}/></td><td><StatusBadge status={i.operational_status==="1"?"up":"down"}/></td><td>{i.speed_bps?formatBits(i.speed_bps):"Unknown"}</td><td>{fmt(i.last_seen_at)}</td><td><StatusBadge status={i.is_missing?"missing":"present"}/></td><td><Link to={`/snmp/interfaces/${i.id}`}>Inspect</Link></td></tr>)}</Table>}
function InterfaceDetail({id}:{id:string}){const item=useRequest(()=>endpoints.snmpInterface(id),[id]),changes=useRequest(()=>endpoints.snmpInterfaceChanges(id),[id]),metrics=useRequest(()=>endpoints.snmpInterfaceMetrics(id,{page_size:100}),[id]);if(item.loading||item.error||!item.data)return <Feedback loading={item.loading} error={item.error} onRetry={item.reload}/>;const i=item.data;return <><SectionTitle title={i.name||`Interface ${i.interface_index}`} copy={i.description||"Interface inventory record"} action={<Link className="secondary-action" to="/snmp/interfaces">Back</Link>}/><section className="snmp-health-cards"><MetricCard label="Admin" value={i.admin_status==="1"?"Up":"Down"}/><MetricCard label="Operational" value={i.operational_status==="1"?"Up":"Down"} quality={i.operational_status==="1"?"good":"warning"}/><MetricCard label="Speed" value={i.speed_bps?formatBits(i.speed_bps):"Unknown"}/><MetricCard label="Last seen" value={fmt(i.last_seen_at)}/></section><div className="snmp-dashboard-grid"><Panel title="Identity" copy="ifIndex remains authoritative; names may change."><dl className="snmp-detail-grid"><Detail label="ifIndex" value={i.interface_index}/><Detail label="Alias" value={i.alias}/><Detail label="MAC" value={i.mac_address}/><Detail label="MTU" value={i.mtu}/><Detail label="First seen" value={fmt(i.first_seen_at)}/><Detail label="Missing since" value={fmt(i.missing_since)}/></dl></Panel><Panel title="Change history" copy="Only meaningful changes are retained.">{changes.data?.items.map(c=><article className="snmp-timeline" key={c.id}><i/><div><strong>{c.change_type.replaceAll("_"," ")}</strong><span>{fmt(c.detected_at)}</span><small>{c.changed_fields.join(", ")||"Inventory created"}</small></div></article>)}</Panel></div><Panel title="Traffic and quality" copy="Reset, wrapped, stale, and unsupported samples remain explicit."><MetricChart metrics={metrics.data?.items??[]} metricKey={(metrics.data?.items??[])[0]?.metric_key}/></Panel></>}

function PollRuns({user}:{user:User}){const data=useRequest(()=>endpoints.snmpPollRuns({page_size:100}),[]);if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;return <><SectionTitle title="Poll run monitoring" copy="Manual approved collection lifecycle and safe failures."/><RunTable rows={data.data.items} admin={user.role==="admin"}/></>}
function RunTable({rows,admin=false}:{rows:SNMPPollRun[];admin?:boolean}){if(!rows.length)return <Feedback empty="No poll runs have been recorded."/>;return <Table heads={["Target","Type","Trigger","Status","Started","Duration","OIDs","Error","Actions"]}>{rows.map(r=><tr key={r.id}><td className="snmp-mono">{r.target_id}</td><td>{r.poll_type}</td><td>{r.trigger_type}</td><td><StatusBadge status={r.status}/></td><td>{fmt(r.started_at)}</td><td>{duration(r.duration_ms)}</td><td>{r.successful_oids}/{r.requested_oids}<small>{r.failed_oids} failed</small></td><td>{r.error_category||"—"}<small>{r.error_summary||""}</small></td><td><Link to={`/snmp/poll-runs/${r.id}`}>View</Link>{admin&&["pending","running"].includes(r.status)&&<button onClick={()=>void endpoints.cancelSNMPPoll(r.id)}>Cancel</button>}</td></tr>)}</Table>}
function PollDetail({id,user}:{id:string;user:User}){const run=useRequest(()=>endpoints.snmpPollRun(id),[id]),results=useRequest(()=>endpoints.snmpPollResults(id),[id]);if(run.loading||run.error||!run.data)return <Feedback loading={run.loading} error={run.error} onRetry={run.reload}/>;return <><SectionTitle title={`Poll ${id.slice(0,8)}`} copy={`${run.data.poll_type} · ${run.data.status}`} action={<Link className="secondary-action" to="/snmp/poll-runs">Back</Link>}/><section className="snmp-health-cards"><MetricCard label="Status" value={run.data.status}/><MetricCard label="Duration" value={duration(run.data.duration_ms)}/><MetricCard label="Successful OIDs" value={run.data.successful_oids}/><MetricCard label="Failed OIDs" value={run.data.failed_oids} quality={run.data.failed_oids?"warning":"good"}/></section>{user.role==="admin"&&["pending","running"].includes(run.data.status)&&<button className="danger-action" onClick={()=>void endpoints.cancelSNMPPoll(id).then(run.reload)}>Cancel run</button>}<Panel title="Collected results" copy="Safe normalized values, never raw packets."><MetricTable rows={results.data?.items??[]}/></Panel></>}

function MetricExplorer(){const targets=useRequest(()=>endpoints.snmpTargets({page_size:100}),[]),[target,setTarget]=useState(""),[key,setKey]=useState("device.uptime_seconds");const metrics=useRequest(()=>target?endpoints.snmpTargetMetrics(target,{metric_key:key,page_size:100}):Promise.resolve({items:[],total:0,page:1,page_size:100}),[target,key]);return <><SectionTitle title="Metric explorer" copy="Select from approved metric keys; arbitrary OIDs are unavailable."/><div className="snmp-toolbar"><label>Target<select value={target} onChange={e=>setTarget(e.target.value)}><option value="">Select target</option>{targets.data?.items.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label>Metric key<input list="metric-keys" value={key} onChange={e=>setKey(e.target.value)}/><datalist id="metric-keys">{["device.uptime_seconds","device.response_time_ms","device.cpu_percent","device.memory_percent","device.temperature_celsius","interface.in_bps","interface.out_bps","interface.in_utilization_percent","interface.out_utilization_percent","printer.toner_percent","ups.battery_charge_percent","ups.load_percent","ap.client_count"].map(k=><option key={k}>{k}</option>)}</datalist></label></div>{!target?<Feedback emptyTitle="Select a target" empty="Metric queries remain idle until a target is selected."/>:metrics.loading||metrics.error?<Feedback loading={metrics.loading} error={metrics.error} onRetry={metrics.reload}/>:<><MetricChart metrics={metrics.data?.items??[]} metricKey={key}/><MetricTable rows={metrics.data?.items??[]}/></>}</>}
function MetricChart({metrics,metricKey}:{metrics:SNMPMetric[];metricKey?:string}){const rows=metrics.filter(m=>!metricKey||m.metric_key===metricKey).filter(m=>m.value_numeric!=null).slice(-60),max=Math.max(1,...rows.map(m=>Number(m.value_numeric))),width=640,height=180,points=rows.map((m,i)=>`${rows.length===1?width/2:i/(rows.length-1)*width},${height-12-Number(m.value_numeric)/max*(height-24)}`).join(" ");if(!rows.length)return <Feedback empty="No numeric samples support this chart yet."/>;return <div className="snmp-chart"><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${metricKey||"Metric"} trend with ${rows.length} samples`}><polyline points={points}/></svg><div><span>{fmt(rows[0].observed_at)}</span><strong>{metricKey}</strong><span>{fmt(rows.at(-1)?.observed_at)}</span></div><p className="sr-only">{rows.map(m=>`${fmt(m.observed_at)}: ${value(m)}, quality ${m.quality}`).join("; ")}</p></div>}
function MetricTable({rows}:{rows:SNMPMetric[]}){if(!rows.length)return <Feedback empty="No metric samples are available."/>;return <Table heads={["Metric","Interface","Value","Quality","Observed","Reason"]}>{rows.map(m=><tr key={m.id}><td>{m.metric_key}</td><td>{m.interface_name??m.interface_index??"Device"}</td><td>{value(m)}</td><td><StatusBadge status={m.quality}/></td><td>{fmt(m.observed_at)}</td><td>{m.quality_reason||"—"}</td></tr>)}</Table>}

function StateChanges(){const [type,setType]=useState("");const data=useRequest(()=>endpoints.snmpStateChanges({page_size:100,state_type:type}),[type]);if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;return <><SectionTitle title="State-change history" copy="Safe operational evidence; no Alert records are created here."/><div className="snmp-toolbar"><label>State type<select value={type} onChange={e=>setType(e.target.value)}><option value="">All types</option>{["device_reboot","sys_name_changed","sys_location_changed","sys_object_id_changed","interface_identity_conflict"].map(t=><option key={t}>{t}</option>)}</select></label></div><Table heads={["Time","Target","Interface","State","Previous","Current","Severity","Evidence"]}>{data.data.items.map(s=><tr key={s.id}><td>{fmt(s.detected_at)}</td><td className="snmp-mono">{s.target_id}</td><td>{s.interface_id||"Device"}</td><td>{s.state_type.replaceAll("_"," ")}</td><td>{s.previous_value||"—"}</td><td>{s.current_value||"—"}</td><td><StatusBadge status={s.severity_hint}/></td><td><code>{JSON.stringify(s.evidence)}</code>{s.state_type==="device_reboot"&&<small>Counter rate baselines reset after reboot.</small>}</td></tr>)}</Table></>}
function StateList({rows}:{rows:SNMPStateChange[]}){if(!rows.length)return <Feedback empty="No state changes recorded."/>;return <div>{rows.map(s=><article className="snmp-timeline" key={s.id}><i/><div><strong>{s.state_type.replaceAll("_"," ")}</strong><span>{fmt(s.detected_at)}</span><small>{s.previous_value||"—"} → {s.current_value||"—"}</small></div></article>)}</div>}

function Retention({user}:{user:User}){const data=useRequest(endpoints.snmpRetentionPreview,[]),[notice,setNotice]=useState("");if(user.role!=="admin")return <Feedback error="Administrator access is required for retention management."/>;if(data.loading||data.error||!data.data)return <Feedback loading={data.loading} error={data.error} onRetry={data.reload}/>;return <><SectionTitle title="Metric retention" copy="Preview-first cleanup preserves audit, onboarding, links, interfaces, and state history."/><section className="snmp-health-cards"><MetricCard label="Expired metrics" value={data.data.expired_metrics}/><MetricCard label="Expired empty runs" value={data.data.expired_empty_poll_runs}/><MetricCard label="Metric cutoff" value={fmt(data.data.metric_cutoff)}/><MetricCard label="Poll-run cutoff" value={fmt(data.data.poll_run_cutoff)}/></section><Panel title="Manual cleanup" copy="No cleanup scheduler is registered."><p className="snmp-warning">Cleanup permanently removes only eligible raw metrics and empty old poll runs. It does not remove audit or onboarding history.</p><button className="danger-action" disabled={!data.data.expired_metrics&&!data.data.expired_empty_poll_runs} onClick={()=>{if(confirm("Delete the previewed expired metric data?"))void endpoints.runSNMPRetentionCleanup().then(r=>{setNotice(`Deleted ${r.deleted_metrics??0} metrics and ${r.deleted_poll_runs??0} empty runs.`);void data.reload()}).catch(e=>setNotice(message(e)))}}>Run previewed cleanup</button></Panel>{notice&&<Toast message={notice}/>}</>}
function SNMPReports(){const targets=useRequest(()=>endpoints.snmpTargets({page_size:100}),[]),interfaces=useRequest(()=>endpoints.snmpInterfaces({page_size:100}),[]),runs=useRequest(()=>endpoints.snmpPollRuns({page_size:100}),[]),candidates=useRequest(()=>endpoints.snmpCandidates({page_size:100}),[]);if(targets.loading||targets.error||!targets.data)return <Feedback loading={targets.loading} error={targets.error} onRetry={targets.reload}/>;const reports=[["Target health",`${targets.data.items.filter(t=>health(t)==="healthy").length} healthy of ${targets.data.total}`],["Poll success/failure",`${runs.data?.items.filter(r=>r.status==="completed").length??0} completed · ${runs.data?.items.filter(r=>r.status==="failed").length??0} failed`],["Interface inventory",`${interfaces.data?.total??0} total · ${interfaces.data?.items.filter(i=>i.operational_status!=="1").length??0} down`],["Pending candidates",String(candidates.data?.items.filter(c=>c.review_status!=="approved").length??0)],["Reboots and state changes","Open the state-change report for retained evidence"],["Storage and retention","Open retention for current cleanup eligibility"]];return <><SectionTitle title="SNMP reports" copy="Real bounded operational summaries. Export remains unavailable until a dedicated safe backend report endpoint exists."/><section className="snmp-report-grid">{reports.map(([title,copy])=><article key={title}><h3>{title}</h3><p>{copy}</p></article>)}</section></>}

function Panel({title,copy,children}:{title:string;copy:string;children:ReactNode}){return <section className="snmp-panel"><header><h2>{title}</h2><p>{copy}</p></header>{children}</section>}
function SectionTitle({title,copy,action}:{title:string;copy:string;action?:ReactNode}){return <div className="snmp-section-title"><div><h2>{title}</h2><p>{copy}</p></div>{action}</div>}
function Table({heads,children}:{heads:string[];children:ReactNode}){return <div className="snmp-table-wrap"><table className="snmp-table"><thead><tr>{heads.map(h=><th key={h} scope="col">{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}
function Detail({label,value}:{label:string;value:unknown}){return <div><dt>{label}</dt><dd>{value==null||value===""?"—":String(value)}</dd></div>}
function MetricCard({label,value:cardValue,quality}:{label:string;value:unknown;quality?:string}){return <article className="snmp-metric-card"><span>{label}</span><strong>{String(cardValue)}</strong>{quality&&<StatusBadge status={quality}/>}</article>}
function MetricSummary({metrics}:{metrics:Record<string,SNMPMetric>}){const keys=Object.keys(metrics);if(!keys.length)return <Feedback empty="No supported performance metrics have been collected."/>;return <div className="snmp-summary-grid">{keys.slice(0,8).map(key=><MetricCard key={key} label={key.replaceAll("."," ")} value={value(metrics[key])} quality={metrics[key].quality}/>)}</div>}
function latestMetrics(metrics:SNMPMetric[]){return metrics.reduce<Record<string,SNMPMetric>>((all,item)=>{if(!all[item.metric_key]||new Date(item.observed_at)>new Date(all[item.metric_key].observed_at))all[item.metric_key]=item;return all},{})}
function HealthBars({targets}:{targets:SNMPTarget[]}){const groups=["healthy","failed","disabled","unknown"].map(name=>({name,value:targets.filter(t=>health(t)===name).length})),max=Math.max(1,...groups.map(g=>g.value));return <div className="snmp-bars">{groups.map(g=><div key={g.name}><span>{g.name}</span><i><b style={{width:`${g.value/max*100}%`}}/></i><strong>{g.value}</strong></div>)}</div>}
function formatBits(bits:number){if(bits>=1e9)return `${(bits/1e9).toFixed(1)} Gbps`;if(bits>=1e6)return `${(bits/1e6).toFixed(1)} Mbps`;if(bits>=1e3)return `${(bits/1e3).toFixed(1)} Kbps`;return `${bits} bps`}
